<template>
  <div class="module-page"><div class="page-header-row"><div><span class="eyebrow">আবাসিক ব্যবস্থাপনা</span><h1>হোস্টেল কক্ষ</h1><p>কক্ষ, ধারণক্ষমতা, আবাসিক অবস্থা ও ওয়ার্ডেন পরিচালনা করুন</p></div><button class="btn btn-primary" @click="showForm=!showForm"><icon name="plus" /> নতুন কক্ষ</button></div><div class="toolbar card"><div class="search-box"><icon name="search" /><input v-model="search" placeholder="কক্ষ বা ব্লক খুঁজুন..." @keyup.enter="load" /></div><select v-model="availability" class="form-control compact" @change="load"><option value="">সব কক্ষ</option><option value="true">খালি আছে</option><option value="false">পূর্ণ/অনুপলব্ধ</option></select><button class="btn btn-outline btn-sm" @click="load"><icon name="refresh" /> রিফ্রেশ</button></div><form v-if="showForm" class="create-panel card" @submit.prevent="createRoom"><div class="form-heading"><h2>নতুন হোস্টেল কক্ষ</h2><button type="button" class="close-btn" @click="showForm=false">×</button></div><div v-if="error" class="alert alert-error">{{ error }}</div><div class="form-grid"><div class="form-group"><label>কক্ষ নম্বর *</label><input v-model="form.room_number" class="form-control" required /></div><div class="form-group"><label>ব্লক</label><input v-model="form.block" class="form-control" /></div><div class="form-group"><label>তলা</label><input v-model.number="form.floor" type="number" class="form-control" /></div><div class="form-group"><label>ধারণক্ষমতা</label><input v-model.number="form.capacity" type="number" min="1" class="form-control" /></div><div class="form-group"><label>মাসিক ভাড়া</label><input v-model.number="form.monthly_rent" type="number" min="0" class="form-control" /></div></div><div class="form-actions"><button class="btn btn-primary" :disabled="saving">{{ saving?'সংরক্ষণ হচ্ছে...':'কক্ষ তৈরি করুন' }}</button><button type="button" class="btn btn-ghost" @click="showForm=false">বাতিল</button></div></form><div v-if="loading" class="loading-state"><div class="spinner" /></div><div v-else-if="!rooms.length" class="empty-card"><div class="empty-icon"><icon name="building" /></div><h3>কোনো হোস্টেল কক্ষ নেই</h3><p>আবাসিক ব্যবস্থাপনা শুরু করতে প্রথম কক্ষটি যোগ করুন</p></div><div v-else class="room-grid"><article v-for="room in rooms" :key="room.id" class="room-card"><div class="room-top"><span class="room-number">কক্ষ {{ room.room_number }}</span><span class="status" :class="room.is_available?'available':'occupied'">{{ room.is_available?'খালি':'পূর্ণ' }}</span></div><div class="room-illustration"><icon name="building" /></div><div class="room-info"><h3>{{ room.block || 'প্রধান ভবন' }} <small>{{ room.floor ? `· ${room.floor} তলা` : '' }}</small></h3><div class="occupancy"><span>দখল</span><strong>{{ room.current_occupancy || 0 }}/{{ room.capacity || 0 }}</strong><div class="track"><i :style="{width:`${occupancy(room)}%`}" /></div></div><div class="room-meta"><span>৳{{ Number(room.monthly_rent||0).toLocaleString('bn-BD') }}/মাস</span><span>{{ room.warden?.name_bn || 'ওয়ার্ডেন নির্ধারিত নয়' }}</span></div></div></article></div></div>
</template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{useApiClient}from'~/utils/api';const api=useApiClient();const rooms=ref<any[]>([]);const loading=ref(true);const saving=ref(false);const showForm=ref(false);const error=ref('');const search=ref('');const availability=ref('');const form=reactive({room_number:'',block:'',floor:1,capacity:4,monthly_rent:0});async function load(){loading.value=true;try{const q=new URLSearchParams();if(search.value)q.set('search',search.value);if(availability.value)q.set('is_available',availability.value);const r=await api.get(`/hostel-rooms?${q}`);rooms.value=r.data?.data?.data||r.data?.data||[]}catch(e){console.error(e)}finally{loading.value=false}}async function createRoom(){saving.value=true;error.value='';try{await api.post('/hostel-rooms',form);showForm.value=false;form.room_number='';form.block='';await load()}catch(e:any){error.value=e?.response?.data?.message||'কক্ষ তৈরি করা যায়নি'}finally{saving.value=false}}function occupancy(r:any){return Math.min(100,Math.round((Number(r.current_occupancy||0)/Math.max(Number(r.capacity||1),1))*100))}onMounted(load)</script>
<style scoped>.module-page{max-width:1400px;margin:0 auto;padding-bottom:2rem}.page-header-row{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin-bottom:1.4rem}.eyebrow{color:var(--color-primary);font:600 .78rem var(--font-bn)}.page-header-row h1{margin:.25rem 0;color:var(--color-primary);font:700 1.65rem var(--font-bn)}.page-header-row p{color:var(--color-text-light);font:.88rem var(--font-bn)}.toolbar{display:flex;gap:.7rem;padding:.7rem;margin-bottom:1rem}.search-box{display:flex;align-items:center;gap:.5rem;flex:1;padding:0 .75rem;background:var(--color-bg-muted);border-radius:10px}.search-box input{width:100%;padding:.65rem 0;border:0;outline:0;background:transparent;font:.86rem var(--font-bn)}.form-control.compact{width:150px}.create-panel{padding:1.2rem;margin-bottom:1rem}.form-heading{display:flex;justify-content:space-between;margin-bottom:1rem}.form-heading h2{font:700 1rem var(--font-bn)}.close-btn{border:0;background:transparent;font-size:1.5rem;color:var(--color-text-muted);cursor:pointer}.form-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:.7rem}.form-group label{display:block;margin-bottom:.3rem;font:600 .78rem var(--font-bn)}.form-actions{display:flex;gap:.6rem;margin-top:1rem}.room-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.room-card{padding:1rem;background:#fff;border:1px solid var(--color-border-light);border-radius:17px;box-shadow:var(--shadow-sm);transition:.2s}.room-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-md)}.room-top,.room-meta,.occupancy{display:flex;justify-content:space-between;align-items:center;gap:.5rem}.room-number{color:var(--color-primary);font:700 .9rem var(--font-bn)}.status{padding:.24rem .6rem;border-radius:99px;font:.7rem var(--font-bn)}.status.available{color:#19724a;background:#e6f4ec}.status.occupied{color:#a05c35;background:#fff0e4}.room-illustration{display:grid;place-items:center;height:95px;margin:1rem 0;border-radius:13px;color:var(--color-primary);background:linear-gradient(135deg,var(--color-primary-50),#eef8f3);font-size:2.1rem}.room-info h3{font:700 .9rem var(--font-bn)}.room-info h3 small{color:var(--color-text-muted);font:400 .72rem var(--font-bn)}.occupancy{margin-top:.7rem;color:var(--color-text-light);font:.7rem var(--font-bn)}.occupancy strong{color:var(--color-text);font:700 .78rem var(--font-sans)}.track{height:6px;flex:1;overflow:hidden;background:#edf1f2;border-radius:99px}.track i{display:block;height:100%;background:var(--color-primary);border-radius:inherit}.room-meta{padding-top:.7rem;margin-top:.7rem;border-top:1px solid var(--color-border-light);color:var(--color-text-muted);font:.68rem var(--font-bn)}.empty-card{padding:3rem;text-align:center;background:#fff;border:1px dashed var(--color-border);border-radius:18px}.empty-icon{display:grid;place-items:center;width:54px;height:54px;margin:0 auto 1rem;border-radius:16px;color:var(--color-primary);background:var(--color-primary-50);font-size:1.4rem}.empty-card h3{font:700 1rem var(--font-bn)}.empty-card p{color:var(--color-text-light);font:.8rem var(--font-bn)}@media(max-width:1100px){.room-grid{grid-template-columns:repeat(3,1fr)}.form-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){.page-header-row{align-items:flex-start;flex-direction:column}.toolbar{flex-wrap:wrap}.search-box{min-width:100%}.room-grid{grid-template-columns:repeat(2,1fr)}.form-grid{grid-template-columns:1fr}}@media(max-width:450px){.room-grid{grid-template-columns:1fr}}
</style>
